mapper.insert:
INSERT INTO productImages (
    productIdx, imgOrder, originalName, saveName, imgUrl
) VALUES (
    #{productIdx}, #{imgOrder}, #{originalName}, #{saveName}, #{imgUrl}
)

mapper.select:
SELECT * FROM (
    SELECT ROWNUM rnum, tb.* FROM (
        SELECT 
            p.productIdx, p.title, p.price, p.userIdx, p.hitCount, p.likeCount, p.chatCount,
            p.tradeType, p.tradeStatus, p.productStatus, p.createdDate,
            (SELECT imgUrl FROM productImages WHERE productIdx = p.productIdx AND imgOrder = 1) as imgUrl
        FROM product p


                AND (p.title LIKE '%' || #{keyword} || '%' OR p.content LIKE '%' || #{keyword} || '%')


                AND p.categoryIdx = #{categoryIdx}


        ORDER BY p.productIdx DESC
    ) tb WHERE ROWNUM <= #{end}
) WHERE rnum >= #{start}

SELECT COUNT(*) FROM product


        AND (title LIKE '%' || #{keyword} || '%' OR content LIKE '%' || #{keyword} || '%')


        AND categoryIdx = #{categoryIdx}

SELECT saveName 
FROM productImages 
WHERE productIdx = #{productIdx} AND imgOrder = #{imgOrder}

SELECT NVL(MAX(imgOrder), 0) 
FROM productImages 
WHERE productIdx = #{productIdx}
